package com.gymmind.membership.infrastructure.persistence; import com.gymmind.membership.domain.model.Order; import com.gymmind.membership.domain.repository.OrderRepository; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository; import java.util.Optional; interface SpringDataOrderRepository extends JpaRepository<Order,Long>{Optional<Order> findByTenantIdAndId(Long t,Long id);} @Repository class JpaOrderRepository implements OrderRepository{private final SpringDataOrderRepository d;JpaOrderRepository(SpringDataOrderRepository d){this.d=d;}public Order save(Order o){return d.save(o);}public Optional<Order> findByTenantIdAndId(Long t,Long id){return d.findByTenantIdAndId(t,id);}}
